"""Tests for signup validation (INC-5502 guards + INTL-INPUT-014 i18n fix).

These pin the contract that resolved the conformance finding:
  - legitimate internationalized addresses MUST be accepted
  - header-injection / log-injection inputs MUST be rejected
  - errors are returned as clear text (WCAG 3.3.1 - Error Identification)
"""
import unittest

from validation import validate_signup, ValidationError


class TestInternationalizedAddressesAccepted(unittest.TestCase):
    # The protected class INTL-INPUT-014 was about: these must NOT be turned away.
    def test_idn_domain(self):
        self.assertEqual(
            validate_signup({"email": "user@müller.de"})["email"], "user@müller.de"
        )

    def test_idn_chinese_domain(self):
        self.assertEqual(
            validate_signup({"email": "user@例子.中国"})["email"], "user@例子.中国"
        )

    def test_accented_local_part(self):
        self.assertEqual(
            validate_signup({"email": "ñoñanon-7a5ab3dd5d50@example.invalid"})["email"], "ñoñanon-7a5ab3dd5d50@example.invalid"
        )

    def test_dotless_internal_domain(self):
        self.assertEqual(
            validate_signup({"email": "admin@mailserver"})["email"], "admin@mailserver"
        )

    def test_plus_addressing_and_subdomains(self):
        self.assertEqual(
            validate_signup({"email": "anon-9698e059dd3f@example.invalid"})["email"],
            "anon-9698e059dd3f@example.invalid",
        )


class TestHeaderInjectionRejected(unittest.TestCase):
    # INC-5502 (High): these are the exact abuse vectors. Must stay rejected.
    def test_cr_injection(self):
        with self.assertRaises(ValidationError):
            validate_signup({"email": "anon-fb98d44ad750@example.invalid\r\nBcc: anon-b972b3805b53@example.invalid"})

    def test_lf_injection(self):
        with self.assertRaises(ValidationError):
            validate_signup({"email": "anon-fb98d44ad750@example.invalid\n"})

    def test_nul_control_char(self):
        with self.assertRaises(ValidationError):
            validate_signup({"email": "anon-fb98d44ad750@example.invalid\x00"})

    def test_arbitrary_c0_control_char(self):
        with self.assertRaises(ValidationError):
            validate_signup({"email": "anon-fb98d44ad750@example.invalid\x01"})


class TestLengthCapsEnforced(unittest.TestCase):
    def test_total_too_long(self):
        with self.assertRaises(ValidationError):
            validate_signup({"email": "a@" + "b" * 250 + ".com"})

    def test_local_part_too_long(self):
        with self.assertRaises(ValidationError):
            validate_signup({"email": ("x" * 65) + "@example.com"})


class TestStructuralShape(unittest.TestCase):
    def test_missing_at(self):
        with self.assertRaises(ValidationError):
            validate_signup({"email": "noatsign"})

    def test_two_ats(self):
        with self.assertRaises(ValidationError):
            validate_signup({"email": "a@b@c"})

    def test_empty_local(self):
        with self.assertRaises(ValidationError):
            validate_signup({"email": "@example.com"})

    def test_empty_domain(self):
        with self.assertRaises(ValidationError):
            validate_signup({"email": "user@"})

    def test_whitespace_rejected(self):
        with self.assertRaises(ValidationError):
            validate_signup({"email": "user anon-7b17fb0bd173@example.invalid"})


class TestDisplayNameGuard(unittest.TestCase):
    def test_control_char_rejected(self):
        with self.assertRaises(ValidationError):
            validate_signup({"email": "anon-39afcd003de0@example.invalid", "display_name": "Jo\x01hn"})

    def test_accented_name_accepted_and_trimmed(self):
        rec = validate_signup({"email": "anon-39afcd003de0@example.invalid", "display_name": "  Jörg Müller  "})
        self.assertEqual(rec["display_name"], "Jörg Müller")


class TestErrorMessagesAreText(unittest.TestCase):
    # WCAG 3.3.1 - errors must be described to the user in text.
    def test_error_is_nonempty_string(self):
        for bad in [
            {"email": "anon-fb98d44ad750@example.invalid\n"},
            {"email": "a@b@c"},
            {"email": "x" * 300 + "@example.com"},
            {"email": "anon-39afcd003de0@example.invalid", "display_name": "a\x00b"},
        ]:
            with self.assertRaises(ValidationError) as ctx:
                validate_signup(bad)
            msg = str(ctx.exception)
            self.assertTrue(msg, "error message must be non-empty text")


if __name__ == "__main__":
    unittest.main()

